import Phaser from "phaser";
import { onSettingsChange, settings } from "../settings";

type Bus = "music" | "ambience" | "sfx";

/** Every sound file the game loads (client/public/assets/audio, generated by tools/audio/build.py). */
export const AUDIO_KEYS = [
  "music_soramei_night",
  "amb_night_wind",
  "sfx_title_gong",
  "sfx_cin_split",
  "sfx_gate_bang",
  "sfx_dodge",
  "ui_click",
  "ui_hover",
  "ui_confirm",
  ...[0, 1, 2, 3].flatMap((i) => [`sfx_step_stone_${i}`, `sfx_step_soft_${i}`]),
  "music_gate_fight",
  ...["whisper", "choir", "growl", "crackle"].flatMap((k) => [0, 1].map((i) => `sfx_chant_${k}_${i}`)),
  ...["blade", "blade_heavy", "blade_spin", "whoosh", "gore", "hit_flesh", "gong_small", "roots", "slam", "blood", "blood_heavy", "fire", "fire_heavy", "wind", "thunder", "spirit", "spirit_heavy", "poison", "bell", "bow", "bow_heavy", "throw", "blowpipe", "smoke", "drink", "greyed_death", "tapper_roar", "horn", "revive", "downed", "execute", "victory", "burst", "groan_0", "groan_1", "groan_2"].map((k) => `sfx_${k}`),
];

interface Loop {
  sound: Phaser.Sound.WebAudioSound;
  key: string;
  /** 0..1 fade level, multiplied with the bus volume. */
  level: number;
  tween?: Phaser.Tweens.Tween;
}

/**
 * Music, ambience and effects on three volume buses. Loops crossfade; positional effects are
 * panned and attenuated by distance from the camera centre.
 */
export class AudioDirector {
  private music: Loop | null = null;
  private ambience: Loop | null = null;
  private readonly unsubscribe: () => void;

  constructor(private readonly scene: Phaser.Scene) {
    this.unsubscribe = onSettingsChange(() => this.applyVolumes());
  }

  private busVolume(bus: Bus) {
    return (settings.master / 100) * (settings[bus] / 100);
  }

  private applyVolumes() {
    for (const [loop, bus] of [[this.music, "music"], [this.ambience, "ambience"]] as const) {
      if (loop) loop.sound.setVolume(loop.level * this.busVolume(bus));
    }
  }

  private crossfade(current: Loop | null, key: string, bus: Bus, fadeMs: number): Loop | null {
    if (current?.key === key) return current;
    if (current) this.fadeOut(current, fadeMs);
    if (!this.scene.cache.audio.exists(key)) return null;
    const sound = this.scene.sound.add(key, { loop: true, volume: 0 }) as Phaser.Sound.WebAudioSound;
    sound.play();
    const loop: Loop = { sound, key, level: 0 };
    loop.tween = this.scene.tweens.add({
      targets: loop,
      level: 1,
      duration: fadeMs,
      onUpdate: () => sound.setVolume(loop.level * this.busVolume(bus)),
    });
    return loop;
  }

  private fadeOut(loop: Loop, fadeMs: number) {
    loop.tween?.stop();
    const startVolume = loop.sound.volume;
    this.scene.tweens.addCounter({
      from: 1,
      to: 0,
      duration: fadeMs,
      onUpdate: (tw) => loop.sound.setVolume(startVolume * (tw.getValue() ?? 0)),
      onComplete: () => loop.sound.destroy(),
    });
  }

  playMusic(key: string, fadeMs = 3000) {
    this.music = this.crossfade(this.music, key, "music", fadeMs);
  }

  playAmbience(key: string, fadeMs = 2500) {
    this.ambience = this.crossfade(this.ambience, key, "ambience", fadeMs);
  }

  /** A one-shot effect; with a screen position it is panned and quieter further from the camera. */
  play(key: string, volume = 1, at?: { x: number; y: number }, rate = 1) {
    if (!this.scene.cache.audio.exists(key)) return;
    let vol = volume * this.busVolume("sfx");
    let pan = 0;
    if (at) {
      const cam = this.scene.cameras.main;
      const dx = at.x - cam.midPoint.x;
      const dy = at.y - cam.midPoint.y;
      const dist = Math.hypot(dx, dy * 1.6);
      vol *= Math.max(0, 1 - dist / 1400) ** 1.5;
      pan = Phaser.Math.Clamp(dx / 700, -0.8, 0.8);
    }
    if (vol < 0.005) return;
    this.scene.sound.play(key, { volume: vol, pan, rate } as Phaser.Types.Sound.SoundConfig);
  }

  destroy() {
    this.unsubscribe();
    this.music?.sound.destroy();
    this.ambience?.sound.destroy();
  }
}
